// 提取关键字段并准备数据
const item = $input.first().json;

// 从「模型选择」列提取模型名称（取 - 前面的部分）
const modelRaw = (item['模型选择'] || '').trim();
const modelName = modelRaw.split('-')[0].trim();

// 模型名称 → OpenRouter model ID 映射
const MODEL_MAP = {
  'Nano Banana 2': 'google/gemini-3.1-flash-image-preview',
  'Nano Banana Pro': 'google/gemini-3-pro-image-preview',
  'GPT': 'openai/gpt-5-image',
  'FLUX.2Pro': 'black-forest-labs/flux.2-pro',
  'FLUX.2 Pro': 'black-forest-labs/flux.2-pro',
  'FLUX.2Max': 'black-forest-labs/flux.2-max',
  'FLUX.2 Max': 'black-forest-labs/flux.2-max'
};

// 匹配模型ID（支持模糊匹配）
let modelId = '';
let isFlux = false;
for (const [key, value] of Object.entries(MODEL_MAP)) {
  if (modelName.toLowerCase().includes(key.toLowerCase()) || key.toLowerCase().includes(modelName.toLowerCase())) {
    modelId = value;
    isFlux = value.startsWith('black-forest-labs');
    break;
  }
}

// 如果没匹配到，尝试更宽松的匹配
if (!modelId) {
  if (modelName.toLowerCase().includes('nano') && modelName.includes('2')) {
    modelId = 'google/gemini-3.1-flash-image-preview';
  } else if (modelName.toLowerCase().includes('nano') && modelName.toLowerCase().includes('pro')) {
    modelId = 'google/gemini-3-pro-image-preview';
  } else if (modelName.toLowerCase().includes('gpt')) {
    modelId = 'openai/gpt-5-image';
  } else if (modelName.toLowerCase().includes('flux') && modelName.toLowerCase().includes('max')) {
    modelId = 'black-forest-labs/flux.2-max';
    isFlux = true;
  } else if (modelName.toLowerCase().includes('flux')) {
    modelId = 'black-forest-labs/flux.2-pro';
    isFlux = true;
  } else {
    // 默认用 Nano Banana 2
    modelId = 'google/gemini-3.1-flash-image-preview';
  }
}

// 尺寸映射
const sizeRaw = (item['尺寸选择'] || '').trim();
let aspectRatio = '1:1';
let imageSize = '1K';
if (sizeRaw.includes('16:9') || sizeRaw.includes('16：9')) aspectRatio = '16:9';
else if (sizeRaw.includes('9:16') || sizeRaw.includes('9：16')) aspectRatio = '9:16';
else if (sizeRaw.includes('4:3') || sizeRaw.includes('4：3')) aspectRatio = '4:3';
else if (sizeRaw.includes('3:4') || sizeRaw.includes('3：4')) aspectRatio = '3:4';
else if (sizeRaw.includes('3:2') || sizeRaw.includes('3：2')) aspectRatio = '3:2';
else if (sizeRaw.includes('2:3') || sizeRaw.includes('2：3')) aspectRatio = '2:3';

if (sizeRaw.includes('2K') || sizeRaw.includes('2k')) imageSize = '2K';
else if (sizeRaw.includes('4K') || sizeRaw.includes('4k')) imageSize = '4K';

// 生成数量
const generateCount = parseInt(item['每次生成数量']) || 1;

// 任务ID
const taskId = item['任务ID'] || `task-${item.row_number}-${Date.now()}`;

// 提示词
const prompt = item['自定义提示词-自动生成-工作流'] || '';

// 产品图链接（可能有多张，用逗号或换行分隔）
const productImageLinks = (item['产品图链接-同产品最多3张'] || '').trim();

// modalities 设置
const modalities = isFlux ? ['image'] : ['image', 'text'];

return [{
  json: {
    modelId,
    modelName,
    isFlux,
    aspectRatio,
    imageSize,
    generateCount,
    taskId,
    prompt,
    productImageLinks,
    modalities,
    row_number: item.row_number,
    originalData: item
  }
}];

// 根据生成数量拆分为多个任务项
const item = $input.first().json;
const count = item.generateCount || 1;
const results = [];

for (let i = 1; i <= count; i++) {
  results.push({
    json: {
      ...item,
      currentIndex: i,
      fileName: `${item.taskId}_${i}.png`
    }
  });
}

return results;

// 下载产品图并转为 base64 (V6 · 方案B无认证版)
// 前提: Drive文件夹必须设为"知道链接的任何人可访问"
// 改动: 使用公开URL访问,跳过OAuth (因为Code节点不支持httpRequestWithAuthentication)
const item = $input.first().json;
const links = item.productImageLinks;

// ========== 视角识别(通过文件名) ==========
function detectView(fileName) {
  const name = (fileName || '').toLowerCase();
  if (/(^|[_\-\s\.])front([_\-\s\.]|$)|正面/.test(name)) return 'front';
  if (/(^|[_\-\s\.])side([_\-\s\.]|$)|侧面/.test(name)) return 'side';
  if (/(^|[_\-\s\.])(back|rear)([_\-\s\.]|$)|背面/.test(name)) return 'back';
  return 'unknown';
}

const VIEW_ORDER = { front: 1, side: 2, back: 3, unknown: 99 };

// ========== 从场景prompt自动推断主视角 ==========
function inferPrimaryViewFromPrompt(prompt) {
  if (!prompt || typeof prompt !== 'string') return 'front';
  const p = prompt.toLowerCase();

  let scoreFront = 0;
  let scoreSide = 0;
  let scoreBack = 0;

  const frontStrong = [
    'facing camera', 'facing the camera', 'looking at camera', 'looking at the camera',
    'looking directly at camera', 'front view', 'frontal angle', 'frontal shot',
    'forward-facing', 'front-facing', 'face-on', 'straight on',
    'head-on', 'direct frontal', 'looking directly into',
    '正面', '面向镜头', '朝向镜头'
  ];
  const frontWeak = [
    'face visible', 'full face', 'eye contact', 'looking up',
    'looking into', 'centered', 'symmetric', 'portrait'
  ];

  const sideStrong = [
    'side view', 'side profile', 'profile shot', 'profile view',
    'side angle', 'from the side', 'sitting sideways', 'lying on side',
    'walking in profile', 'walking sideways', 'side-on',
    '侧面', '侧身', '侧视'
  ];
  const sideWeak = [
    'walking', 'running', 'in motion', 'mid-stride',
    'lateral', 'sideways'
  ];

  const backStrong = [
    'back view', 'from behind', 'rear view', 'rear angle',
    'facing away', 'looking away', 'back to camera',
    'walking away', 'turned away', 'from the back',
    '背面', '背对', '背影', '背向'
  ];
  const backWeak = [
    'over the shoulder', 'looking over shoulder', 'glancing back',
    'tail visible', 'rear'
  ];

  frontStrong.forEach(kw => { if (p.includes(kw)) scoreFront += 3; });
  frontWeak.forEach(kw => { if (p.includes(kw)) scoreFront += 1; });
  sideStrong.forEach(kw => { if (p.includes(kw)) scoreSide += 3; });
  sideWeak.forEach(kw => { if (p.includes(kw)) scoreSide += 1; });
  backStrong.forEach(kw => { if (p.includes(kw)) scoreBack += 3; });
  backWeak.forEach(kw => { if (p.includes(kw)) scoreBack += 1; });

  const threeQuarter = [
    'three-quarter', 'three quarter', '3/4', 'slightly turned',
    'slightly angled', 'head tilted'
  ];
  threeQuarter.forEach(kw => {
    if (p.includes(kw)) scoreFront += 2;
  });

  const maxScore = Math.max(scoreFront, scoreSide, scoreBack);
  if (maxScore === 0) return 'front';
  if (scoreFront >= scoreSide && scoreFront >= scoreBack) return 'front';
  if (scoreBack > scoreSide) return 'back';
  return 'side';
}

// ========== 主视角决策 ==========
function determinePrimaryView(item) {
  const manualView = (item.originalData?.['主要视角'] ||
                      item['主要视角'] ||
                      '').toString().trim().toLowerCase();

  if (['front', '正面'].includes(manualView)) return { view: 'front', source: 'manual' };
  if (['side', '侧面'].includes(manualView)) return { view: 'side', source: 'manual' };
  if (['back', 'rear', '背面'].includes(manualView)) return { view: 'back', source: 'manual' };
  if (['all', 'multi', '多视角', '全部'].includes(manualView)) return { view: 'all', source: 'manual' };

  const promptText = item.prompt || '';
  const inferredView = inferPrimaryViewFromPrompt(promptText);
  return { view: inferredView, source: 'inferred' };
}

if (!links) {
  return [{
    json: {
      ...item,
      productImages: [],
      imageErrors: ['未提供 productImageLinks']
    }
  }];
}

const urls = links
  .split(/[,\n\s]+/)
  .map(u => u.trim())
  .filter(u => u.startsWith('http'));

const rawImages = [];
const errors = [];

// ========== 无认证下载单个Drive文件 ==========
async function downloadPublicDriveFile(fileId, fileName) {
  try {
    const url = `https://drive.google.com/uc?export=download&id=${fileId}`;

    const response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      encoding: 'arraybuffer',
      returnFullResponse: true,
      followRedirect: true,
      timeout: 30000,
      headers: { 'User-Agent': 'Mozilla/5.0' }
    });

    const contentType = response.headers?.['content-type'] || response.headers?.['Content-Type'] || '';

    if (!contentType.startsWith('image/')) {
      errors.push(`文件不是图片: ${fileName} (${fileId}) | type=${contentType} | 提示:文件必须设为公开访问`);
      return;
    }

    const base64 = Buffer.from(response.body).toString('base64');
    rawImages.push({
      fileName: fileName || '',
      view: detectView(fileName),
      image: {
        type: 'image_url',
        image_url: {
          url: `data:${contentType};base64,${base64}`
        }
      }
    });
  } catch (err) {
    errors.push(`Drive文件下载失败: ${fileName || fileId} | ${err.message} | 提示:文件必须设为公开访问`);
  }
}

// ========== 无认证列出文件夹内容 ==========
// 注意:Google Drive没有直接的公开API列出文件夹内容
// 这里用一个变通方案: 解析文件夹的公开HTML页面提取文件ID
async function listPublicDriveFolder(folderId) {
  try {
    const url = `https://drive.google.com/embeddedfolderview?id=${folderId}#list`;
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      timeout: 15000,
      headers: { 'User-Agent': 'Mozilla/5.0' }
    });

    const html = typeof response === 'string' ? response : (response.body || '');
    const files = [];

    // 从HTML中提取文件ID和文件名
    // 文件链接格式: /file/d/{fileId}/view
    const fileRegex = /\/file\/d\/([a-zA-Z0-9_-]+)\/view[^"]*"[^>]*>(?:[^<]*<[^>]*>)*([^<]+?)<\/div>/g;
    // 备用更宽松的正则
    const idRegex = /\/file\/d\/([a-zA-Z0-9_-]+)/g;
    const nameRegex = /<div class="flip-entry-title">([^<]+)<\/div>/g;

    const ids = [];
    let m;
    while ((m = idRegex.exec(html)) !== null) {
      if (!ids.includes(m[1])) ids.push(m[1]);
    }

    const names = [];
    while ((m = nameRegex.exec(html)) !== null) {
      names.push(m[1]);
    }

    // 配对ID和name(按出现顺序)
    for (let i = 0; i < ids.length; i++) {
      files.push({
        id: ids[i],
        name: names[i] || `file_${i}.jpg`
      });
    }

    return files;
  } catch (err) {
    errors.push(`列出文件夹失败: ${folderId} | ${err.message} | 提示:文件夹必须设为公开访问`);
    return [];
  }
}

for (const rawUrl of urls) {
  try {
    // ===== Case 1: Google Drive 文件夹链接 =====
    const folderMatch = rawUrl.match(/drive\.google\.com\/drive\/folders\/([^/?]+)/);
    if (folderMatch && folderMatch[1]) {
      const folderId = folderMatch[1];
      const files = await listPublicDriveFolder.call(this, folderId);

      if (files.length === 0) {
        errors.push(`文件夹为空或无法访问: ${rawUrl} | 请确认文件夹已设为"知道链接的任何人可访问"`);
        continue;
      }

      for (const file of files) {
        await downloadPublicDriveFile.call(this, file.id, file.name);
      }
      continue;
    }

    // ===== Case 2: Google Drive 单文件链接 =====
    const fileMatch = rawUrl.match(/drive\.google\.com\/file\/d\/([^/?]+)/);
    if (fileMatch && fileMatch[1]) {
      await downloadPublicDriveFile.call(this, fileMatch[1], rawUrl);
      continue;
    }

    // ===== Case 3: 普通图片URL =====
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: rawUrl,
      encoding: 'arraybuffer',
      returnFullResponse: true,
      followRedirect: true,
      timeout: 30000,
      headers: { 'User-Agent': 'Mozilla/5.0' }
    });

    const contentType = response.headers?.['content-type'] || response.headers?.['Content-Type'] || '';

    if (!contentType.startsWith('image/')) {
      errors.push(`下载结果不是图片: ${rawUrl} | type=${contentType}`);
      continue;
    }

    const base64 = Buffer.from(response.body).toString('base64');
    const fileName = rawUrl.split('/').pop() || '';
    rawImages.push({
      fileName,
      view: detectView(fileName),
      image: {
        type: 'image_url',
        image_url: { url: `data:${contentType};base64,${base64}` }
      }
    });

  } catch (err) {
    errors.push(`下载失败: ${rawUrl} | ${err.message}`);
  }
}

// 按 front → side → back 排序
rawImages.sort((a, b) => VIEW_ORDER[a.view] - VIEW_ORDER[b.view]);

// ========== 智能筛选主视角参考图 ==========
const { view: primaryView, source: viewSource } = determinePrimaryView(item);

let finalImages;
if (primaryView === 'all') {
  finalImages = rawImages.slice(0, 3);
} else {
  const matchedImages = rawImages.filter(img => img.view === primaryView);

  if (matchedImages.length > 0) {
    finalImages = matchedImages.slice(0, 1);
  } else {
    const frontImages = rawImages.filter(img => img.view === 'front');
    if (frontImages.length > 0) {
      finalImages = frontImages.slice(0, 1);
    } else if (rawImages.length > 0) {
      finalImages = rawImages.slice(0, 1);
    } else {
      finalImages = [];
    }
  }
}

const productImages = finalImages.map(i => i.image);
const productImageViews = finalImages.map(i => i.view);
const productImageNames = finalImages.map(i => i.fileName);

return [{
  json: {
    ...item,
    productImages,
    productImageViews,
    productImageNames,
    imageErrors: errors,
    usedPrimaryView: primaryView,
    primaryViewSource: viewSource
  }
}];

// 组装 OpenRouter API 请求体 (v7 · 严格职责分离)
const item = $input.first().json;

// ========== 从[PRODUCT]段提取否定锚定关键词 ==========
function extractNegativeAnchors(prompt) {
  if (!prompt) return [];
  const productMatch = prompt.match(/\[PRODUCT\]:?\s*([\s\S]*?)(?=\[LIGHTING\]|\[CAMERA\]|\[TEXT\]|\[STYLE\]|$)/i);
  if (!productMatch) return [];
  const productText = productMatch[1];

  const anchors = [];
  const notMatches = productText.match(/NOT\s+[^,.—\n]+/gi) || [];
  notMatches.forEach(m => anchors.push(m.trim()));
  const noMatches = productText.match(/NO\s+[^,.—\n]+/gi) || [];
  noMatches.forEach(m => anchors.push(m.trim()));

  return [...new Set(anchors)];
}

// ========== 动态 System Prompt ==========
const imageCount = (item.productImages || []).length;
const isSingleImage = imageCount <= 1;

// 精简版: 单张参考图时使用(严格职责分离版)
const singleImageSystemPrompt = `You are an expert e-commerce product photographer creating a NEW scene image.

You will receive TWO INPUTS with STRICTLY DIFFERENT ROLES. Understanding this separation is CRITICAL.

═══════════════════════════════════════════
INPUT 1: REFERENCE PHOTO — PRODUCT APPEARANCE ONLY
═══════════════════════════════════════════

The reference photo serves ONE purpose: to show you EXACTLY what the product looks like.

EXTRACT from the photo (copy these):
- Product color (exact shade)
- Product material and texture
- Closure type, count, placement, symmetry (e.g. asymmetric diagonal)
- Collar/neckline shape
- Sleeve length, cuff style
- Hardware color and count
- All structural details (straps, patches, trims, seams)

IGNORE from the photo (DO NOT copy any of these):
- The background (color, texture, setting, any environmental elements)
- The lighting direction, intensity, warmth, or shadow style
- The camera angle, framing, distance, or depth of field
- The pet's breed, fur length, color pattern, or markings (if a pet is wearing the product)
- The pet's pose, expression, positioning, or body language
- Any props, objects, or staging elements

The reference photo is just a PRODUCT CATALOG SHOT or a previous photoshoot. You are NOT reproducing that shoot.
You are TAKING A NEW PHOTOGRAPH in a completely different setting with potentially a different model pet.

═══════════════════════════════════════════
INPUT 2: TEXT PROMPT — THE NEW SCENE TO CREATE
═══════════════════════════════════════════

The text prompt defines EVERYTHING ELSE about the new image. Follow it strictly:

- [SCENE]: The environment, background, setting, props, atmosphere. CREATE this scene from scratch.
- [SUBJECT]: The pet's breed, coat color/pattern, fur length, pose, expression, positioning. This pet may be COMPLETELY DIFFERENT from the pet in the reference photo — you must follow the text description, not the reference photo's pet.
- [LIGHTING]: The light direction, quality, warmth, shadow style. Light the scene as described, NOT as lit in the reference.
- [CAMERA]: The angle, framing, depth of field, lens character. Frame the shot as described.
- [STYLE]: The overall photographic style and quality.

═══════════════════════════════════════════
THE CORE SEPARATION PRINCIPLE
═══════════════════════════════════════════

Think of it this way:
- The reference photo = a PRODUCT SWATCH showing what the garment looks like
- The text prompt = the ART DIRECTOR'S BRIEF for a brand new photoshoot

A product photographer doing a NEW SHOOT never copies the previous catalog's background,
lighting, pet model, or composition. They take the GARMENT, put it on a NEW pet (as briefed),
place them in a NEW setting (as briefed), light them DIFFERENTLY (as briefed), and frame
the shot DIFFERENTLY (as briefed).

You must do exactly that. The output image should look COMPLETELY DIFFERENT from the
reference photo — different background, different lighting, potentially a different pet breed,
different pose, different camera angle. ONLY the product itself should match.

═══════════════════════════════════════════
CONFLICT RESOLUTION — APPLY THIS TEST
═══════════════════════════════════════════

When text and photo seemingly conflict, ask: "Is this about the PRODUCT or about the SCENE/MODEL/FRAMING?"

PHOTO WINS for product appearance:
- Text says "blue jacket" but photo shows brown → render BROWN (photo = product color truth)
- Text says "centered buttons" but photo shows asymmetric diagonal → render ASYMMETRIC (photo = product structure truth)
- Text says "silver hardware" but photo shows brass → render BRASS (photo = hardware truth)
- Text mentions a feature not visible in photo → do NOT render it (photo = ground truth for what exists)

TEXT WINS for everything else:
- Text says "British Shorthair cream cat" but photo shows a Maine Coon silver tabby → render BRITISH SHORTHAIR CREAM (text = model choice)
- Text says "outdoor park scene" but photo has plain studio background → render OUTDOOR PARK (text = scene)
- Text says "three-quarter angle, cat looking up" but photo shows front-facing sitting → render THREE-QUARTER LOOKING UP (text = pose/angle)
- Text says "golden hour warm light from left" but photo has flat studio lighting → render GOLDEN HOUR FROM LEFT (text = lighting)
- Text says "shallow depth of field with blurred background" but photo is fully sharp → render with BLURRED BACKGROUND (text = camera)

═══════════════════════════════════════════
PRODUCT FIDELITY RULES (for the product only)
═══════════════════════════════════════════

1. COLOR: Match the exact color tone from the reference photo. Do not shift hue.
2. MATERIAL: Reproduce the exact surface texture visible in the reference.
3. HARDWARE & CLOSURES: Match type, count, placement, and color exactly.
4. STRUCTURE: Render asymmetric/diagonal closures if shown; render specific collar shapes exactly.
5. DETAILS: If a decoration is not visible in the reference, do NOT add it. If one IS visible, include it.

DO NOT:
- Copy the background from the reference photo
- Copy the lighting setup from the reference photo
- Copy the pet's breed/color/pose from the reference photo — follow [SUBJECT] in the text
- Copy the camera angle from the reference photo — follow [CAMERA] in the text
- "Improve" or "beautify" the product — reproduce it AS-IS
- Default to generic shapes (centered closure, stand-up collar, silver hardware) when the photo shows something specific`;

// 完整版: 多张参考图时使用
const multiImageSystemPrompt = `You are an expert e-commerce product photographer creating a NEW scene image.

You will receive multiple reference photos (front/side/back views) of a REAL product, and a text prompt describing a NEW scene.

═══════════════════════════════════════════
STRICT ROLE SEPARATION
═══════════════════════════════════════════

REFERENCE PHOTOS are for PRODUCT APPEARANCE ONLY:
- Extract: color, material, closures, collar, sleeves, hardware, structure
- IGNORE: background, lighting, pet breed/pose, camera angle, composition

TEXT PROMPT defines the NEW SCENE:
- Follow [SCENE]/[SUBJECT]/[LIGHTING]/[CAMERA]/[STYLE] exactly
- The pet breed, pose, setting, and lighting come from the TEXT, not the photos
- The output must look COMPLETELY DIFFERENT from the reference photos (different background, lighting, pet, composition)

═══════════════════════════════════════════
THREE-VIEW REFERENCE HANDLING (for product appearance only)
═══════════════════════════════════════════
- FRONT VIEW: highest authority for color, front hardware, collar shape
- SIDE VIEW: authority for sleeve length, cuff style, silhouette
- BACK VIEW: authority for back panel, rear details, hem

═══════════════════════════════════════════
CONFLICT RESOLUTION
═══════════════════════════════════════════

PHOTO WINS for product appearance (color, closure, hardware, material, structure).
TEXT WINS for scene, lighting, camera, pet breed, pose, and composition.

DO NOT:
- Copy the background, lighting, or pet from the reference photos
- Add product features not visible in any reference view
- Substitute closures or hardware colors
- "Improve" the product`;

const systemPrompt = isSingleImage ? singleImageSystemPrompt : multiImageSystemPrompt;

// ========== 构建 user message content ==========
const content = [];

const hasImages = item.productImages && item.productImages.length > 0;
const views = item.productImageViews || [];
const names = item.productImageNames || [];
const hasViewLabels = views.some(v => v && v !== 'unknown');

// 提取否定锚定用于参考图观察清单
const negativeAnchors = extractNegativeAnchors(item.prompt);
const anchorText = negativeAnchors.length > 0
  ? `\n\nCRITICAL NEGATIVE ANCHORS from the product description (common mistakes to AVOID when rendering the product):\n${negativeAnchors.map(a => `- ${a}`).join('\n')}`
  : '';

if (hasImages) {
  if (isSingleImage) {
    // ============ 单图模式 ============
    const viewLabel = views[0] || 'unknown';
    const viewName = {
      front: 'FRONT VIEW',
      side: 'SIDE VIEW',
      back: 'BACK VIEW',
      unknown: 'PRODUCT REFERENCE'
    }[viewLabel] || 'PRODUCT REFERENCE';

    content.push({
      type: 'text',
      text: `═══════════════════════════════════════════
PRODUCT REFERENCE PHOTO (${viewName})
═══════════════════════════════════════════

⚠️ This photo shows the EXACT product to reproduce in terms of APPEARANCE ONLY.

STUDY ONLY these product details:
- Exact shade of color
- Type and COUNT of closures (snap? button? velcro? zipper?)
- Symmetric vs asymmetric closure structure
- Hardware color (silver / gold / brass / black — be exact)
- Collar/neckline EXACT shape
- Sleeve length and cuff style
- Material and texture
- Any signature details${anchorText}

⚠️ DO NOT copy from this photo:
- The background (you will create a NEW scene from the text prompt)
- The lighting (you will use the lighting described in the text)
- The pet's breed, coat, pose, or expression (you will follow the [SUBJECT] in the text)
- The camera angle or framing (you will follow the [CAMERA] in the text)`
    });

    content.push(item.productImages[0]);

    content.push({
      type: 'text',
      text: `═══════════════════════════════════════════
