// ========== 构建消息数组 ==========
let messages = [];

if (!item.isFlux) {
  messages = [
    {
      role: 'system',
      content: systemPrompt
    },
    {
      role: 'user',
      content: content
    }
  ];
} else {
  messages = [
    {
      role: 'user',
      content: item.prompt
    }
  ];
}

// ========== 构建请求体 ==========
const requestBody = {
  model: item.modelId,
  messages: messages,
  modalities: item.modalities,
  image_config: {
    aspect_ratio: item.aspectRatio,
    image_size: item.imageSize
  }
};

const requestBodyString = JSON.stringify(requestBody);

return [
  {
    json: {
      fileName: item.fileName,
      taskId: item.taskId,
      row_number: item.row_number,
      currentIndex: item.currentIndex,
      generateCount: item.generateCount,
      modelId: item.modelId,
      modelName: item.modelName,
      isFlux: item.isFlux,
      aspectRatio: item.aspectRatio,
      imageSize: item.imageSize,
      prompt: item.prompt,
      productImages: item.productImages,
      productImageViews: item.productImageViews,
      productImageNames: item.productImageNames,
      imageErrors: item.imageErrors,
      originalData: item.originalData,
      requestBody,
      requestBodyString
    }
  }
];

// 解析 OpenRouter 返回，提取 base64 图片
const item = $input.first().json;
const response = item.body || item;

try {
  let data = response;
  if (typeof response === 'string') {
    data = JSON.parse(response);
  }

  if (data.error) {
    throw new Error(`API Error: ${JSON.stringify(data.error)}`);
  }

  const choices = data.choices || [];
  if (choices.length === 0) {
    throw new Error('No choices in response');
  }

  const message = choices[0].message || {};

  let imageDataUrl = '';

  // 方式1: images 数组（标准格式）
  if (message.images && message.images.length > 0) {
    imageDataUrl = message.images[0].image_url?.url || '';
  }

  // 方式2: content 中的 image_url
  if (!imageDataUrl && message.content) {
    if (Array.isArray(message.content)) {
      for (const part of message.content) {
        if (part.type === 'image_url' && part.image_url?.url) {
          imageDataUrl = part.image_url.url;
          break;
        }
      }
    } else if (typeof message.content === 'string' && message.content.startsWith('data:image')) {
      imageDataUrl = message.content;
    }
  }

  if (!imageDataUrl) {
    throw new Error('No image found in response. Raw: ' + JSON.stringify(data).substring(0, 500));
  }

  let imageBase64 = '';
  if (imageDataUrl.startsWith('data:')) {
    imageBase64 = imageDataUrl.split(',')[1];
  } else {
    imageBase64 = imageDataUrl;
  }

  // 从上游获取字段
  const upstream = $('组装API请求').first().json;

  return [{
    json: {
      success: true,
      imageBase64,
      fileName: upstream.fileName,
      taskId: upstream.taskId,
      row_number: upstream.row_number,
      currentIndex: upstream.currentIndex,
      generateCount: upstream.generateCount
    }
  }];

} catch (err) {
  const upstream = $('组装API请求').first().json;
  return [{
    json: {
      success: false,
      error: err.message,
      fileName: upstream.fileName,
      taskId: upstream.taskId,
      row_number: upstream.row_number,
      currentIndex: upstream.currentIndex,
      generateCount: upstream.generateCount
    }
  }];
}

// 将 base64 转为 binary 以便上传到 Google Drive
const item = $input.first().json;
const buffer = Buffer.from(item.imageBase64, 'base64');

return [{
  json: {
    fileName: item.fileName,
    taskId: item.taskId,
    row_number: item.row_number,
    currentIndex: item.currentIndex,
    generateCount: item.generateCount
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'image/png',
      fileName: item.fileName
    }
  }
}];

// 生成 Google Drive 分享链接
const item = $input.first().json;
const driveFileId = item.id;
const driveLink = `https://drive.google.com/file/d/${driveFileId}/view`;

// 从上游获取 row_number 等信息
const upstream = $('base64转Binary').first().json;

return [{
  json: {
    driveFileId,
    driveLink,
    fileName: upstream.fileName,
    taskId: upstream.taskId,
    row_number: upstream.row_number,
    currentIndex: upstream.currentIndex,
    generateCount: upstream.generateCount
  }
}];

// 聚合本轮成功的链接，存入静态变量，然后回到循环
const item = $input.first().json;

// Code 节点里要用 $getWorkflowStaticData，不要用 this.getWorkflowStaticData
const staticData = $getWorkflowStaticData('global');

if (!staticData.driveLinks) {
  staticData.driveLinks = [];
}

// 存链接
if (item.driveLink) {
  staticData.driveLinks.push(item.driveLink);
}

// 把当前信息继续往后传，并告诉下游继续循环
return [
  {
    json: {
      ...item,
      _loopback: true
    }
  }
];

// 失败时也回到循环继续处理下一张
const item = $input.first().json;
return [{ json: { ...item, _loopback: true, _failed: true } }];

// 所有循环结束，从 static data 取出所有链接，聚合回填
const staticData = $getWorkflowStaticData('global');
const allLinks = staticData.driveLinks || [];

// 从循环前固定下来的参数节点读取
const params = $('解析参数+模型路由').first().json;

const result = {
  taskId: params.taskId,
  row_number: params.row_number,
  allLinks: allLinks.join('\n'),
  successCount: allLinks.length,
  generateCount: params.generateCount,
};

// 清空 static data，为下次执行做准备
staticData.driveLinks = [];

if (allLinks.length === 0) {
  return [{ json: { ...result, allFailed: true } }];
}

return [{ json: { ...result, allFailed: false } }];
